import os
import sqlite3
from datetime import datetime
from functools import wraps

from flask import (
    Flask, g, render_template, request, redirect,
    url_for, session, flash, abort
)
from werkzeug.security import generate_password_hash, check_password_hash

APP_ROOT = os.path.dirname(os.path.abspath(__file__))
DB_PATH = os.path.join(APP_ROOT, "physio.db")

app = Flask(__name__)
# In production, set this via an environment variable!
app.secret_key = os.environ.get("SECRET_KEY", "change-me-in-production")

# The single user who can log in. Change the password before using!
USERNAME = os.environ.get("PHYSIO_USER", "therapist")
PASSWORD_HASH = generate_password_hash(
    os.environ.get("PHYSIO_PASSWORD", "secret123")
)


# ---------- Database helpers ----------
def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON")
    return g.db


@app.teardown_appcontext
def close_db(exc):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def init_db():
    db = sqlite3.connect(DB_PATH)
    db.executescript(
        """
        CREATE TABLE IF NOT EXISTS patients (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS notes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            patient_id INTEGER NOT NULL,
            body TEXT NOT NULL,
            created_at TEXT NOT NULL,
            -- if this note is a revision, parent_id points to the previous version
            parent_id INTEGER REFERENCES notes(id),
            FOREIGN KEY (patient_id) REFERENCES patients(id)
        );
        """
    )
    db.commit()
    db.close()


# ---------- Auth helpers ----------
def login_required(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        if not session.get("user"):
            return redirect(url_for("login", next=request.path))
        return f(*args, **kwargs)
    return wrapper


@app.route("/login", methods=["GET", "POST"])
def login():
    if request.method == "POST":
        u = request.form.get("username", "")
        p = request.form.get("password", "")
        if u == USERNAME and check_password_hash(PASSWORD_HASH, p):
            session["user"] = u
            nxt = request.args.get("next") or url_for("patients")
            return redirect(nxt)
        flash("Invalid credentials", "error")
    return render_template("login.html")


@app.route("/logout")
def logout():
    session.clear()
    return redirect(url_for("login"))


# ---------- Routes ----------
@app.route("/")
@login_required
def patients():
    db = get_db()
    rows = db.execute(
        "SELECT * FROM patients ORDER BY name COLLATE NOCASE"
    ).fetchall()
    return render_template("patients.html", patients=rows)


@app.route("/patients/new", methods=["GET", "POST"])
@login_required
def add_patient():
    if request.method == "POST":
        name = request.form.get("name", "").strip()
        if not name:
            flash("Name is required", "error")
        else:
            db = get_db()
            db.execute(
                "INSERT INTO patients (name, created_at) VALUES (?, ?)",
                (name, datetime.utcnow().isoformat(timespec="seconds")),
            )
            db.commit()
            return redirect(url_for("patients"))
    return render_template("add_patient.html")


@app.route("/patients/<int:patient_id>")
@login_required
def patient(patient_id):
    db = get_db()
    p = db.execute("SELECT * FROM patients WHERE id = ?", (patient_id,)).fetchone()
    if p is None:
        abort(404)
    # only "current" notes: those that are not superseded by a newer revision
    rows = db.execute(
        """
        SELECT n.* FROM notes n
        WHERE n.patient_id = ?
          AND NOT EXISTS (SELECT 1 FROM notes c WHERE c.parent_id = n.id)
        ORDER BY n.created_at DESC
        """,
        (patient_id,),
    ).fetchall()
    return render_template("patient.html", patient=p, notes=rows)


@app.route("/patients/<int:patient_id>/notes/new", methods=["GET", "POST"])
@login_required
def new_note(patient_id):
    db = get_db()
    p = db.execute("SELECT * FROM patients WHERE id = ?", (patient_id,)).fetchone()
    if p is None:
        abort(404)
    if request.method == "POST":
        body = request.form.get("body", "").strip()
        if not body:
            flash("Note body is required", "error")
        else:
            db.execute(
                "INSERT INTO notes (patient_id, body, created_at) VALUES (?, ?, ?)",
                (patient_id, body,
                 datetime.utcnow().isoformat(timespec="seconds")),
            )
            db.commit()
            return redirect(url_for("patient", patient_id=patient_id))
    return render_template("new_note.html", patient=p)


@app.route("/notes/<int:note_id>/edit", methods=["GET", "POST"])
@login_required
def edit_note(note_id):
    db = get_db()
    note = db.execute("SELECT * FROM notes WHERE id = ?", (note_id,)).fetchone()
    if note is None:
        abort(404)
    if request.method == "POST":
        body = request.form.get("body", "").strip()
        if not body:
            flash("Note body is required", "error")
        else:
            # create a NEW note (revision), keep the old one intact
            db.execute(
                "INSERT INTO notes (patient_id, body, created_at, parent_id) "
                "VALUES (?, ?, ?, ?)",
                (note["patient_id"], body,
                 datetime.utcnow().isoformat(timespec="seconds"),
                 note["id"]),
            )
            db.commit()
            return redirect(url_for("patient", patient_id=note["patient_id"]))
    return render_template("edit_note.html", note=note)


@app.route("/notes/<int:note_id>/history")
@login_required
def note_history(note_id):
    db = get_db()
    # find the root of the revision chain
    note = db.execute("SELECT * FROM notes WHERE id = ?", (note_id,)).fetchone()
    if note is None:
        abort(404)
    root_id = note_id
    seen = set()
    while True:
        if root_id in seen:
            break
        seen.add(root_id)
        row = db.execute(
            "SELECT parent_id FROM notes WHERE id = ?", (root_id,)
        ).fetchone()
        if row is None or row["parent_id"] is None:
            break
        root_id = row["parent_id"]
    # walk down the chain
    chain = []
    current = root_id
    while current is not None:
        row = db.execute(
            "SELECT * FROM notes WHERE id = ?", (current,)
        ).fetchone()
        if row is None:
            break
        chain.append(row)
        nxt = db.execute(
            "SELECT id FROM notes WHERE parent_id = ? ORDER BY id LIMIT 1",
            (current,),
        ).fetchone()
        current = nxt["id"] if nxt else None
    patient = db.execute(
        "SELECT * FROM patients WHERE id = ?", (note["patient_id"],)
    ).fetchone()
    return render_template(
        "patient.html", patient=patient, notes=[note], history=chain
    )


if __name__ == "__main__":
    init_db()
    app.run(debug=True, host="127.0.0.1", port=5000)
