### `templates/patients.html`

```html
{% extends "base.html" %}
{% block content %}
<h1>Patients</h1>
<ul>
  {% for p in patients %}
    <li>
      <a href="{{ url_for('patient', patient_id=p.id) }}">{{ p.name }}</a>
      <span class="meta"> &middot; added {{ p.created_at[:10] }}</span>
    </li>
  {% else %}
    <li class="meta">No patients yet.</li>
  {% endfor %}
</ul>
<p><a class="btn" href="{{ url_for('add_patient') }}">+ Add patient</a></p>
{% endblock %}
```

