### `templates/patient.html`

```html
{% extends "base.html" %}
{% block content %}
<h1>{{ patient.name }}</h1>
<p><a class="btn" href="{{ url_for('new_note', patient_id=patient.id) }}">+ New visit note</a></p>

{% if history %}
  <h2>Revision history</h2>
  {% for h in history %}
    <div class="card">
      <div class="meta">{{ h.created_at }}{% if loop.first %} — original{% endif %}</div>
      <div style="white-space: pre-wrap;">{{ h.body }}</div>
    </div>
  {% endfor %}
  <p><a href="{{ url_for('patient', patient_id=patient.id) }}">← Back to current notes</a></p>
{% else %}
  {% for n in notes %}
    <div class="card">
      <div class="meta">{{ n.created_at }}</div>
      <div style="white-space: pre-wrap;">{{ n.body }}</div>
      <p>
        <a class="btn btn-small" href="{{ url_for('edit_note', note_id=n.id) }}">Edit (create revision)</a>
        <a class="btn btn-small btn-secondary" href="{{ url_for('note_history', note_id=n.id) }}">History</a>
      </p>
    </div>
  {% else %}
    <p class="meta">No notes yet for this patient.</p>
  {% endfor %}
{% endif %}
{% endblock %}
```

